const express=require("express"),router=express.Router(),systemController=require("../controllers/systemController.min.js"),cache=require("../route_cache.js"),TWELVE_HOURS=43200,{redis,isConnected,reconnect}=require("../config/redis");router.get("/initial-fetch",systemController.inital_fetch),router.get("/health/redis",async(e,t)=>{try{if(!isConnected())return console.log("Redis not connected, attempting reconnection..."),reconnect(),t.status(503).json({status:"error",message:"Redis not connected, attempting reconnection"});await redis.ping(),t.json({status:"ok",message:"Redis connected and responding",isConnected:isConnected()})}catch(e){console.error("Redis health check failed:",e),t.status(503).json({status:"error",message:"Redis health check failed",error:e.message})}}),module.exports=router;